'use client';
import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { getSoulType } from '@/lib/soul-engine';
import { supabase } from '@/lib/supabase';
import { saveProfile, saveReading, getCachedReading } from '@/lib/auth';
import { FIXED_READINGS } from '@/lib/fixed-readings';
import { LIFE_SEASONS } from '@/lib/life-seasons';
import Backdrop, { SOUL_TONES } from '../../components/Backdrop';

const BG: Record<string, string> = {
  '灯の民': "data:image/webp;base64,",
  '星渡りの民': "data:image/webp;base64,",
  '花の民': "data:image/webp;base64,",
  '大樹の民': "data:image/webp;base64,",
  '炎の民': "data:image/webp;base64,",
  '風の民': "data:image/webp;base64,",
  '雫の民': "data:image/webp;base64,",
};


interface Reading {
  monthlyTheme: string;
  monthFlow: string;
  shadowReading: string;
  homework: string;
  today: string;
  catchphrase: string;
  cached?: boolean;
}

interface Props {
  params: Promise<{ star: string }>;
}

function getYearMonth() {
  const now = new Date();
  return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
}
function LoadingSteps() {
  const steps = [
    'あなたの民を確認しています...',
    '月の影を読み解いています...',
    '今月の星空と重ねています...',
    'あなただけの言葉を紡いでいます...',
  ];
  const [current, setCurrent] = useState(0);
  const [fade, setFade] = useState(true);

  useEffect(() => {
    const interval = setInterval(() => {
      setFade(false);
      setTimeout(() => {
        setCurrent(i => (i + 1) % steps.length);
        setFade(true);
      }, 400);
    }, 2200);
    return () => clearInterval(interval);
  }, []);

  return (
    <div style={{
      background: 'rgba(246,241,229,0.75)',
      backdropFilter: 'blur(8px)',
      borderRadius: 3,
      padding: '40px 24px',
      textAlign: 'center',
      marginBottom: 24,
    }}>
      <div style={{
        width: 1, height: 48, background: '#CBBFA6',
        margin: '0 auto 32px',
        animation: 'pulse 2s ease-in-out infinite',
      }} />
      <div style={{
        fontSize: 12, color: '#5A5142',
        letterSpacing: '0.3em', lineHeight: 2,
        opacity: fade ? 1 : 0,
        transition: 'opacity 0.4s ease',
      }}>
        {steps[current]}
      </div>
      <style>{`
        @keyframes pulse {
          0%, 100% { opacity: 0.3; transform: scaleY(0.6); }
          50% { opacity: 1; transform: scaleY(1); }
        }
      `}</style>
    </div>
  );
}


export default function ResultPage({ params }: Props) {
  const router = useRouter();
  const [star, setStar] = useState('');
  const [soulData, setSoulData] = useState<ReturnType<typeof getSoulType> | null>(null);
  const [reading, setReading] = useState<Reading | null>(null);
  const [loading, setLoading] = useState(true);
  const [visible, setVisible] = useState(false);
  const [shadowInfo, setShadowInfo] = useState<{ mainId: string; mainName: string; academicName: string; subName: string } | null>(null);
  const [lifeSeasonName, setLifeSeasonName] = useState<string | null>(null);
  const [monthSeasonName, setMonthSeasonName] = useState<string | null>(null);

  useEffect(() => {
    params.then(async p => {
      const decoded = decodeURIComponent(p.star);
      setStar(decoded);

      const bdStr = sessionStorage.getItem('lunaria_birthday');
      let soul: ReturnType<typeof getSoulType>;
      let birthInfo: any = null;

      if (bdStr) {
        birthInfo = JSON.parse(bdStr);
        soul = getSoulType(birthInfo);
        try { await saveProfile(birthInfo); } catch (e) { console.error(e); }
      } else {
        soul = {
          mainStar: decoded, subStar: '花の民', hiddenStar: '雫の民',
          destinyNumber: 7, soulAge: '若魂', element: '光', composition: [],
        } as ReturnType<typeof getSoulType>;
      }
      setSoulData(soul);

      if (birthInfo) {
        const { getShadowComposition } = await import('@/lib/moon-shadow-engine');
        const { MOON_SHADOWS } = await import('@/lib/moon-shadows');
        const { getSeasonComposition } = await import('@/lib/astro');

        const shadow = getShadowComposition(birthInfo);
        const mainShadow = MOON_SHADOWS[shadow.main];
        const subShadow = MOON_SHADOWS[shadow.sub];
        setShadowInfo({
          mainId: shadow.main,
          mainName: mainShadow?.name ?? '',
          academicName: mainShadow?.academicName ?? '',
          subName: subShadow?.name ?? '',
        });

        const seasons = getSeasonComposition(birthInfo);
        setLifeSeasonName(LIFE_SEASONS[seasons.lifeSeason]?.name ?? '');
        setMonthSeasonName(LIFE_SEASONS[seasons.monthSeason]?.name ?? '');
      }

      const yearMonth = getYearMonth();
      try {
        const cached = await getCachedReading(yearMonth);
        if (cached) {
          setReading(cached as Reading);
          setLoading(false);
          setTimeout(() => setVisible(true), 300);
          return;
        }
      } catch (e) { console.error(e); }

      const { data: { session } } = await supabase.auth.getSession();

      try {
        const res = await fetch('/api/reading', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            star: decoded,
            subStar: soul.subStar,
            hiddenStar: soul.hiddenStar,
            destinyNumber: soul.destinyNumber,
            soulAge: soul.soulAge,
            element: soul.element,
            userId: session?.user?.id ?? null,
            birthInfo,
          }),
        });
        const data = await res.json();
        setReading(data);
        if (session?.user?.id) await saveReading(yearMonth, decoded, data);
      } catch (e) { console.error(e); }
      finally {
        setLoading(false);
        setTimeout(() => setVisible(true), 300);
      }
    });
  }, [params]);

  const fixed = FIXED_READINGS[star];

  const panel = (label: string, content: string) => (
    <div style={{
      background: 'rgba(246,241,229,0.94)',
      border: '1px solid #CFC3A9', borderRadius: 3,
      boxShadow: '0 0 0 5px rgba(246,241,229,0.94), 0 0 0 6px #CFC3A9, 0 18px 50px rgba(90,81,66,0.07)',
      padding: '28px 24px', marginBottom: 24,
    }}>
      <div style={{ fontSize: 10, letterSpacing: '0.4em', color: '#8C816C', marginBottom: 14 }}>
        {label}
      </div>
      <p style={{ fontSize: 14, fontWeight: 300, lineHeight: 2.3, color: '#5A5142' }}>
        {content}
      </p>
    </div>
  );

  return (
    <div style={{
      position: 'fixed', inset: 0,
      background: BG[star] ? `url("${BG[star]}") center/cover no-repeat` : 'radial-gradient(ellipse 130% 95% at 50% 32%, #F5F0E4 0%, #EEE6D4 100%)',
      overflowY: 'auto',
      fontFamily: "'Noto Serif JP', serif",
      WebkitFontSmoothing: 'antialiased',
    }}>
      {loading && (
        <div style={{ maxWidth: 380, margin: '0 auto', padding: '72px 28px 0' }}>
          <LoadingSteps />
        </div>
      )}
      <div style={{
        position: 'relative', zIndex: 2,
        maxWidth: 380, margin: '0 auto',
        padding: '72px 28px 80px',
        opacity: visible ? 1 : 0,
        transform: visible ? 'none' : 'translateY(12px)',
        transition: 'opacity 2.5s ease 0.4s, transform 2.5s ease 0.4s',
      }}>

        {/* ── ヘッダー ── */}
<div style={{
  background: 'rgba(246,241,229,0.75)',
  backdropFilter: 'blur(8px)',
  borderRadius: 3,
  padding: '28px 24px 24px',
  marginBottom: 36,
}}>
  <div style={{
    fontFamily: "'Cormorant Garamond', serif",
    fontSize: 11, letterSpacing: '0.5em', color: '#8C816C', marginBottom: 12,
  }}>
    あなたは
  </div>
  <h1 style={{
    fontSize: 'clamp(26px, 7vw, 34px)', fontWeight: 200,
    letterSpacing: '0.3em', color: '#5A5142', marginBottom: 20,
  }}>
    {star}
  </h1>

  {soulData && (
    <div style={{ fontSize: 11, color: '#8C816C', letterSpacing: '0.2em', marginBottom: 24 }}>
      {soulData.element} · 運命数{soulData.destinyNumber} · {soulData.soulAge}
    </div>
  )}

  <div style={{ width: 24, height: 1, background: '#CBBFA6', margin: '0 0 24px' }} />

  {shadowInfo && (
    <>
      <div style={{
        fontFamily: "'Cormorant Garamond', serif",
        fontStyle: 'italic', fontSize: 16,
        color: '#5A5142', letterSpacing: '0.15em',
        marginBottom: 6, lineHeight: 1.6,
      }}>
        {shadowInfo.mainName}
      </div>
      <div style={{
        fontSize: 12, color: '#5A5142',
        letterSpacing: '0.1em', marginBottom: 10,
      }}>
        {shadowInfo.academicName}
      </div>
    </>
  )}

  {lifeSeasonName && monthSeasonName && (
    <div style={{
      fontSize: 11, color: '#8C816C',
      letterSpacing: '0.2em', marginBottom: 20,
    }}>
      人生は{lifeSeasonName}の季節 · 今月は{monthSeasonName}の季節
    </div>
  )}

  {shadowInfo && (
    <button
      onClick={() => router.push(`/insight/${encodeURIComponent(shadowInfo.mainId)}`)}
      style={{
        background: 'transparent',
        border: '1px solid #CBBFA6',
        borderRadius: 2,
        padding: '8px 20px',
        fontFamily: "'Cinzel', serif",
        fontSize: 10, letterSpacing: '0.3em',
        color: '#8C816C', cursor: 'pointer',
      }}
    >
      詳しく見る →
    </button>
  )}
</div>

        <div style={{ width: 1, height: 36, background: '#CBBFA6', margin: '0 auto 36px' }} />

        {/* ── 固定パート ── */}
        {fixed && (
          <>
            {panel('基本性格', fixed.personality)}
            {panel('恋愛傾向', fixed.love)}
            {panel('仕事', fixed.work)}

            <div style={{ textAlign: 'center', padding: '20px 0 32px' }}>
              <div style={{ fontSize: 10, letterSpacing: '0.4em', color: '#8C816C', marginBottom: 10 }}>
                あなたの花
              </div>
              <div style={{ fontSize: 20, fontWeight: 200, letterSpacing: '0.3em', color: '#5A5142', marginBottom: 6 }}>
                {fixed.flower}
              </div>
              <div style={{
                fontFamily: "'Cormorant Garamond', serif",
                fontStyle: 'italic', fontSize: 12, color: '#8C816C', letterSpacing: '0.2em',
              }}>
                「{fixed.hanakotoba}」
              </div>
            </div>

            <div style={{ width: 1, height: 32, background: '#CBBFA6', margin: '0 auto 36px' }} />
          </>
        )}

        {/* ── 月替わりパート ── */}
        {reading && (
          <>
            <p style={{
              fontFamily: "'Cormorant Garamond', serif",
              fontStyle: 'italic', fontSize: 14,
              letterSpacing: '0.2em', color: '#8C816C',
              marginBottom: 32, lineHeight: 1.9, textAlign: 'center',
            }}>
              {reading.catchphrase}
            </p>

            <div style={{
              background: 'rgba(246,241,229,0.94)',
              border: '1px solid #CFC3A9', borderRadius: 3,
              boxShadow: '0 0 0 5px rgba(246,241,229,0.94), 0 0 0 6px #CFC3A9, 0 18px 50px rgba(90,81,66,0.07)',
              padding: '28px 24px', marginBottom: 24,
            }}>
              <div style={{ fontSize: 10, letterSpacing: '0.4em', color: '#8C816C', marginBottom: 14 }}>
                今月のテーマ
              </div>
              <p style={{ fontSize: 17, fontWeight: 300, color: '#5A5142', letterSpacing: '0.2em', lineHeight: 1.8 }}>
                {reading.monthlyTheme}
              </p>
            </div>

            {panel('今月の流れ', reading.monthFlow)}
            {reading.shadowReading && panel('あなたの物語', reading.shadowReading)}
            {panel('今月の宿題', reading.homework)}
            {panel('今日のことば', reading.today)}
          </>
        )}

        <button
          onClick={() => router.push('/fortune')}
          style={{
            display: 'block', margin: '40px auto 0',
            background: 'transparent', border: 'none',
            borderBottom: '1px solid #CBBFA6',
            padding: '0 6px 6px',
            fontFamily: "'Noto Serif JP', serif",
            fontSize: 11, letterSpacing: '0.5em',
            color: '#8C816C', cursor: 'pointer',
          }}
        >
          もう一度、星に尋ねる
        </button>
      </div>
    </div>
  );
}
